fn solve(input: Vec<char>) -> Vec<char> {
    // Mapping from digit character to good count
    let good_count = |c: char| -> u8 {
        match c {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => unreachable!(), // First two chars are guaranteed to be digits
        }
    };
    
    // Get the first two characters (input length is at least 2)
    let first_digit = input[0];
    let second_digit = input[1];
    
    // Calculate the product of good counts
    let product = good_count(first_digit) as u16 * good_count(second_digit) as u16;
    
    // Convert product to string and collect as chars
    let mut result: Vec<char> = product.to_string().chars().collect();
    
    // Append newline character
    result.push('\n');
    
    result
}